phone_emails = {c.get('email') for c in all_phone_contacts}
venmo_emails = {f.get('email') for f in all_venmo_friends}

# Phone contacts not in venmo
missing_from_venmo = phone_emails - venmo_emails
print("Phone contacts not in venmo:")
for email in sorted(missing_from_venmo):
    print(f"  {email}")

# Venmo friends not in phone contacts
extra_in_venmo = venmo_emails - phone_emails
print("\nVenmo friends not in phone contacts:")
for email in sorted(extra_in_venmo):
    print(f"  {email}")

# Let's compute which phone contacts are still missing from venmo
current_venmo_emails = {f.get('email') for f in all_venmo_friends}
phone_emails = {c.get('email') for c in all_phone_contacts}
still_missing = phone_emails - current_venmo_emails
print("Still missing from venmo:")
for email in sorted(still_missing):
    print(f"  {email}")

