# Let's examine all playlists and their song IDs
for pl in all_playlists:
    print(f"Playlist {pl['playlist_id']} - {pl['title']}: {pl['song_ids']}")

# Collect all song IDs from all playlists
all_song_ids = set()
for playlist in playlist_library:
    for song_id in playlist['song_ids']:
        all_song_ids.add(song_id)
print("All song IDs:", sorted(all_song_ids))

# Get details for each song ID and check if it matches any old song
matching_song_ids = []
for song_id in sorted(all_song_ids):
    song = apis.spotify.show_song(song_id=song_id, access_token=spotify_token)
    # Check if this song matches any old song
    for old in old_songs:
        if song['title'] == old['title']:
            # Check if all artists match (order may differ, but we can compare sets)
            song_artist_names = {artist['name'] for artist in song['artists']}
            old_artist_names = set(old['artists'])
            if song_artist_names == old_artist_names:
                matching_song_ids.append(song_id)
                break
print("Matching song IDs:", matching_song_ids)

